          items: [["A", ["Measure A · Improve the contrasts", "Maßnahme A · Kontraste verbessern"]], ["B", ["Measure B · Simplify the navigation", "Maßnahme B · Navigation vereinfachen"]], ["C", ["Measure C · Provide alternative content", "Maßnahme C · Alternative Inhalte bereitstellen"]]],
          cols: [["impact", ["Impact", "Wirkung"]], ["effort", ["Effort", "Aufwand"]], ["risk", ["Risk", "Risiko"]]],
          hints: { first: ["the measure you assess", "die Maßnahme, die Sie bewerten"], impact: ["how many learners it frees, and how badly they were blocked", "wie viele Lernende sie befreit und wie stark sie blockiert waren"], effort: ["how much work and how many people it needs", "wie viel Arbeit und wie viele Personen sie braucht"], risk: ["what could go wrong or take longer than the time allows", "was schiefgehen oder länger dauern könnte, als die Zeit erlaubt"] },
          exFirst: ["Larger signs in a museum", "Größere Schilder in einem Museum"],
